220	  const superseded = [];
221	  const keep = held.map(asEntry).filter((e) => {
222	    // Only the conversion's own placeholder is replaced, never an entry somebody wrote:
223	    // a batch carrying an earlier born would otherwise silently delete real history, and
224	    // the point of this lane is to correct a date the conversion never knew.
225	    if (born && e.kind === 'born' && e.date >= born && CONVERTED_TITLE.test(e.title ?? '')) { superseded.push(headingOf(e)); return false; }
226	    return true;
227	  });
228	  const merged = [...keep];
229	  for (const e of entries) if (!merged.some((m) => headingOf(m) === headingOf(e))) merged.push(e);
230	  // A stable sort by date alone: entries of one day keep the order they arrived in,
231	  // the file's own first and then the batch's, which is the order a run wrote them.
232	  const ordered = merged.map((e, i) => ({ e, i })).sort((a, b) => a.e.date.localeCompare(b.e.date) || a.i - b.i).map(({ e }) => e);
233	  if (ordered.length && firstKind && ordered[0].kind !== firstKind) problems.push(`the file would open with ${ordered[0].kind}; the first entry of a file is ${firstKind}`);
234	  const retiredAt = ordered.findIndex((e) => e.kind === 'retired');
235	  if (retiredAt !== -1 && retiredAt !== ordered.length - 1) problems.push(`a retired entry is a file's last; "${headingOf(ordered[retiredAt])}" would sit above ${ordered.length - 1 - retiredAt} more`);
236	  if (ordered.filter((e) => e.kind === 'born').length > 1) problems.push('the batch would leave two born entries in one file; an element is born once');
237	  if (problems.length) return { problems, superseded };
238	  return { problems: [], superseded, text: ordered.map((e) => renderEntry(e)).join('\n') };
239	}
