241	// Parse an entry written in the file grammar (what `append` reads from stdin).
242	export function parseEntryText(text) {
243	  const { entries, errors } = parseEntries(text, { kinds: [...KINDS, DECLINED_KIND] });
244	  if (entries.length !== 1) return { problems: [`expected exactly one entry, found ${entries.length}`] };
245	  if (errors.length) return { problems: errors.map((e) => `line ${e.line}: ${e.what}`) };
246	  const e = entries[0];
247	  const fields = {};
248	  for (const name of e.order) fields[name] = e.fields[name];
249	  return { problems: [], entry: { date: e.date, kind: e.kind, title: e.title, fields } };
250	}
